# Prototype reference implementation, config-driven, to confirm all five values cohere.
from netsim.topo import RingTopo, TreeTopo
from netsim.net import Mininet
from netsim.graph import WeightedGraph
from netsim.targets.configs import SDN_EXPERIMENTS

class FlowRule:
    def __init__(self, match_fields, actions, priority=100, idle_timeout=0, hard_timeout=0):
        self.match_fields=dict(match_fields); self.actions=list(actions)
        self.priority=priority; self.idle_timeout=idle_timeout; self.hard_timeout=hard_timeout
        self.packet_count=0; self.byte_count=0; self.install_time=0.0
    def is_expired(self, current_time, last_matched_time):
        if self.idle_timeout and current_time-last_matched_time >= self.idle_timeout: return True
        if self.hard_timeout and current_time-self.install_time >= self.hard_timeout: return True
        return False

class FlowTable:
    def __init__(self, switch_name, capacity=4096):
        self.switch_name=switch_name; self.capacity=capacity; self.rules=[]
    def install(self, rule):
        if len(self.rules)>=self.capacity: return False
        self.rules.append(rule); return True
    def size(self): return len(self.rules)
    def evict_expired(self, current_time, last_matched_times):
        ev=[r for r in self.rules if r.is_expired(current_time, last_matched_times.get(id(r),0.0))]
        for r in ev: self.rules.remove(r)
        return ev

class Ctrl:
    def __init__(self,name): self.name=name; self.graph=WeightedGraph(); self.tables={}; self.paths={}
    def add_switch(self,s): self.tables.setdefault(s, FlowTable(s)); self.graph.add_node(s)
    def add_link(self,a,b,weight=1): self.graph.add_edge(a,b,weight=weight)
    def topology_discovery(self,net):
        for s in net.switches: self.add_switch(s.name)
        for l in net.links: self.add_link(l.node1.name,l.node2.name)
    def compute_path(self,s,d): return self.graph.shortest_path(s,d)
    def install_path_rules(self,path,sip,dip,priority=100):
        n=0
        for node in path:
            if node in self.tables:
                if self.tables[node].install(FlowRule({"dst_ip":dip},[{"type":"output","port":1}],priority)): n+=1
        return n
    def total_rules_installed(self): return sum(t.size() for t in self.tables.values())
    def install_all_rules(self, hosts_with_ips):
        n=0
        for s,sip in hosts_with_ips.items():
            for d,dip in hosts_with_ips.items():
                if s==d: continue
                p=self.compute_path(s,d)
                if p: self.paths[(s,d)]=(p,sip,dip); n+=self.install_path_rules(p,sip,dip)
        return n
    def handle_link_failure(self,a,b):
        self.graph.remove_edge(a,b); n=0
        for (s,d),(p,sip,dip) in list(self.paths.items()):
            if any((u,v) in ((a,b),(b,a)) for u,v in zip(p,p[1:])):
                np_=self.compute_path(s,d)
                if np_: self.paths[(s,d)]=(np_,sip,dip); n+=self.install_path_rules(np_,sip,dip)
        return n

cfg=SDN_EXPERIMENTS["proactive_tree"]
net=Mininet(topo=TreeTopo(depth=cfg["depth"],fanout=cfg["fanout"],bw=cfg["link_bw"],delay=cfg["link_delay"])); net.start()
c=Ctrl("c0"); c.topology_discovery(net)
c.install_all_rules({h.name:h.ip for h in net.hosts})
rules=c.total_rules_installed(); print("SDN_FLOW_RULES_INSTALLED: %d"%rules)
print("SDN_PATH_CONVERGENCE_TIME: %.2f"%(rules*cfg["rule_install_time_ms"]))

f=SDN_EXPERIMENTS["link_failure"]
net2=Mininet(topo=RingTopo(k=f["num_switches"],n=f["num_hosts_per_switch"],bw=f["link_bw"],delay=f["link_delay"])); net2.start()
c2=Ctrl("c1"); c2.topology_discovery(net2); c2.install_all_rules({h.name:h.ip for h in net2.hosts})
print("SDN_LINK_FAILURE_RECOVERY: %d"%c2.handle_link_failure(*f["failed_link"]))

r=SDN_EXPERIMENTS["reactive_throughput"]
tot_s=r["num_packets"]*r["packet_in_time_ms"]/1000.0
print("SDN_CONTROLLER_THROUGHPUT: %.2f"%(r["num_packets"]/tot_s))

t=SDN_EXPERIMENTS["rule_timeouts"]
tb=FlowTable("s1",capacity=t["capacity"]); lm={}
for i in range(t["num_rules"]):
    ru=FlowRule({"dst_ip":"10.0.0.%d"%i},[{"type":"output","port":1}],idle_timeout=t["idle_timeout"],hard_timeout=t["hard_timeout"])
    tb.install(ru); lm[id(ru)] = t["idle_last_matched"] if i%2==0 else t["active_last_matched"]
print("SDN_RULE_TIMEOUT_EVICTIONS: %d"%len(tb.evict_expired(t["current_time"],lm)))
